// Shared helpers — generated by NOIR
export const uid = (p = '') => p + Math.random().toString(36).slice(2, 10);
export const nowIso = () => new Date().toISOString();
export const ok = (res, data, status = 200) => { res.statusCode = status; res.setHeader('content-type', 'application/json'); res.end(JSON.stringify({ ok: true, data })); };
export const fail = (res, status, message, code = 'ERROR') => { res.statusCode = status; res.setHeader('content-type', 'application/json'); res.end(JSON.stringify({ ok: false, error: message, code })); };
export const readBody = (req) => new Promise((resolve) => {
  let raw = '';
  req.on('data', (c) => { raw += c; if (raw.length > 2e6) { req.destroy(); resolve(null); } });
  req.on('end', () => { try { resolve(raw ? JSON.parse(raw) : {}); } catch { resolve(null); } });
});
export const htmlEsc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
import crypto from 'node:crypto';
// salted PBKDF2 — real password hashing (never plaintext, never bare SHA)
export const hashPw = async (pw) => { const salt = crypto.randomBytes(8).toString('hex'); return 'pbkdf2$' + salt + '$' + crypto.pbkdf2Sync(String(pw), salt, 100000, 32, 'sha256').toString('hex'); };
export const verifyPw = async (pw, stored) => {
  if (!stored) return false;
  const parts = String(stored).split('$');
  if (parts.length !== 3 || parts[0] !== 'pbkdf2') return false;
  const [tag, salt, hex] = parts;
  const computed = crypto.pbkdf2Sync(String(pw), salt, 100000, 32, 'sha256').toString('hex');
  return computed.length === hex.length && crypto.timingSafeEqual(Buffer.from(computed, 'hex'), Buffer.from(hex, 'hex'));
};
